/**
 * Hand-built MP4 fixtures for the clip sample index.
 *
 * Deterministic and committed ON PURPOSE. The two shapes this file produces are
 * exactly the two the clip path has to tell apart, and one of them (the
 * trailer-less fragmented file an HKSV tee cuts) cannot be obtained from a
 * clean `ffmpeg` run — ffmpeg writes `mfra` when it closes normally. A fixture
 * generated by a tool that never reproduces the failure is not a fixture for
 * it.
 */

const box = (type: string, ...payload: readonly Uint8Array[]): Uint8Array => {
  const body = concat(payload)
  const out = new Uint8Array(8 + body.length)
  const view = new DataView(out.buffer)
  view.setUint32(0, out.length)
  for (let i = 0; i < 4; i++) out[4 + i] = type.charCodeAt(i)
  out.set(body, 8)
  return out
}

const concat = (parts: readonly Uint8Array[]): Uint8Array => {
  let len = 0
  for (const p of parts) len += p.length
  const out = new Uint8Array(len)
  let off = 0
  for (const p of parts) {
    out.set(p, off)
    off += p.length
  }
  return out
}

const u32 = (...values: readonly number[]): Uint8Array => {
  const out = new Uint8Array(values.length * 4)
  const view = new DataView(out.buffer)
  values.forEach((v, i) => view.setUint32(i * 4, v))
  return out
}

const zeros = (n: number): Uint8Array => new Uint8Array(n)

export interface Mp4FixtureSpec {
  /** Movie timescale (ticks per second) for `mvhd`. */
  readonly movieTimescale: number
  /** `mvhd.duration`, in movie ticks. `0` is the trailer-less shape. */
  readonly movieDuration: number
  /** Media timescale for the video track's `mdhd`. */
  readonly mediaTimescale: number
  /** `mdhd.duration`, in media ticks. `0` is the trailer-less shape. */
  readonly mediaDuration: number
  /** `stts` run pairs: [sampleCount, sampleDelta] in media ticks. */
  readonly stts: readonly (readonly [number, number])[]
  /** 1-based sync sample numbers for `stss`. `null` omits the box entirely,
   *  which per ISO/IEC 14496-12 means every sample is a sync sample. */
  readonly stss: readonly number[] | null
  /** Per-sample sizes for `stsz`. Empty ⇒ a sample table with no samples. */
  readonly sampleSizes: readonly number[]
  /** Handler type for the one track. Non-`vide` exercises the no-video-track refusal. */
  readonly handlerType?: string
}

/** A short, well-formed progressive clip: 30 samples at 15 fps, IDR every 15. */
export const FASTSTART_CLIP: Mp4FixtureSpec = {
  movieTimescale: 1000,
  movieDuration: 2000,
  mediaTimescale: 15000,
  mediaDuration: 30000,
  stts: [[30, 1000]],
  stss: [1, 16],
  sampleSizes: Array.from({ length: 30 }, (_, i) => 100 + i),
}

/**
 * The HKSV shape, measured 2026-09-20: `mvhd.duration = 0`, `mdhd.duration = 0`,
 * an empty sample table (the `moov` is written up front by
 * `frag_keyframe+empty_moov`; the samples live in `moof`/`trun` and the trailer
 * that would describe them is never written because the tee cuts like a pipe).
 */
export const HKSV_CLIP: Mp4FixtureSpec = {
  movieTimescale: 1000,
  movieDuration: 0,
  mediaTimescale: 15000,
  mediaDuration: 0,
  stts: [],
  stss: null,
  sampleSizes: [],
}

export function buildMp4Fixture(spec: Mp4FixtureSpec): Uint8Array {
  const ftyp = box('ftyp', new Uint8Array([0x69, 0x73, 0x6f, 0x6d]), u32(512), new Uint8Array(0))

  const mvhd = box(
    'mvhd',
    u32(0), // version 0 + flags
    u32(0, 0, spec.movieTimescale, spec.movieDuration),
    u32(0x00010000, 0x01000000),
    zeros(8),
    zeros(36),
    zeros(24),
    u32(2),
  )

  const mdhd = box(
    'mdhd',
    u32(0),
    u32(0, 0, spec.mediaTimescale, spec.mediaDuration),
    u32(0x55c40000),
  )
  const handler = spec.handlerType ?? 'vide'
  const hdlr = box(
    'hdlr',
    u32(0),
    u32(0),
    new Uint8Array([...handler].map((c) => c.charCodeAt(0))),
    zeros(12),
    new Uint8Array([0]),
  )

  const sttsEntries = concat(spec.stts.map(([count, delta]) => u32(count, delta)))
  const stts = box('stts', u32(0), u32(spec.stts.length), sttsEntries)
  const stss =
    spec.stss === null ? null : box('stss', u32(0), u32(spec.stss.length), u32(...spec.stss))
  const stsz = box('stsz', u32(0), u32(0), u32(spec.sampleSizes.length), u32(...spec.sampleSizes))
  const stsc = box('stsc', u32(0), u32(1), u32(1, Math.max(1, spec.sampleSizes.length), 1))
  const stco = box('stco', u32(0), u32(1), u32(0))

  const stbl = box('stbl', stts, ...(stss ? [stss] : []), stsz, stsc, stco)
  const minf = box('minf', box('vmhd', u32(1), u32(0, 0)), stbl)
  const mdia = box('mdia', mdhd, hdlr, minf)
  const trak = box('trak', box('tkhd', u32(0), zeros(80)), mdia)
  const moov = box('moov', mvhd, trak)

  const totalSamples = spec.sampleSizes.reduce((a, b) => a + b, 0)
  const mdat = box('mdat', new Uint8Array(totalSamples))
  return concat([ftyp, moov, mdat])
}
